-- generated by tools/gen-professions.js from professions/seed.js — do not edit by hand
on conflict (slug) do update set labels = excluded.labels;

on conflict (slug) do update set group_slug = excluded.group_slug, pricing_units = excluded.pricing_units, portfolio_kind = excluded.portfolio_kind, labels = excluded.labels, synonyms = excluded.synonyms;
-- active / invite_only / sort_order are NOT overwritten on re-run: the admin owns those once live

on conflict (key) do update set kind = excluded.kind, match = excluded.match, labels = excluded.labels, min_value = excluded.min_value, max_value = excluded.max_value, unit = excluded.unit, allow_custom = excluded.allow_custom,
  options = case when public.filters.admin_edited then public.filters.options else excluded.options end;

on conflict (profession_slug, filter_key) do nothing;

on conflict (key) do update set labels = excluded.labels;
